#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a[15], ans = 0;

    for (int i = 1; i <= 14; ++i) {
        cin >> a[i];
    }

    for (int k = 1; k <= 14; ++k) {
        if (a[k] > 0) {
            long long b[15];
            for (int i = 1; i <= 14; ++i) {
                b[i] = a[i];
            }

            long long add = a[k] / 14;
            int remainder = a[k] % 14;
            b[k] = 0;

            for (int i = 1; i <= 14; ++i) {
                b[i] += add;
            }

            int id = k % 14 + 1;
            while (remainder--) {
                ++b[id];
                id = id % 14 + 1;
            }

            long long sum = 0;
            for (int i = 1; i <= 14; ++i) {
                if (b[i] % 2 == 0) {
                    sum += b[i];
                }
            }

            ans = max(ans, sum);
        }
    }

    cout << ans;
    return 0;
}

